#include <stdlib.h>
#include <string.h>
#include <omp.h>
#include <immintrin.h>

#define KC 256
#define NCW 256

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#else
#define MR 4
#define NR 16
#endif

static float *bufA = NULL, *bufB = NULL;
static size_t capA = 0, capB = 0;

static float *ensure(float **buf, size_t *cap, size_t nfl)
{
    if (nfl > *cap) {
        free(*buf);
        size_t bytes = (nfl * sizeof(float) + 63) & ~(size_t)63;
        *buf = (float *)aligned_alloc(64, bytes);
        *cap = nfl;
    }
    return *buf;
}

static void edge_store(const float *tmp, float *c, int ldc, int mr, int nr, int acc)
{
    for (int r = 0; r < mr; r++)
        for (int j = 0; j < nr; j++) {
            if (acc) c[(size_t)r * ldc + j] += tmp[r * NR + j];
            else     c[(size_t)r * ldc + j]  = tmp[r * NR + j];
        }
}

#if defined(__AVX512F__)

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
#define DECL(r) __m512 c##r##a = _mm512_setzero_ps(), c##r##b = _mm512_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
#undef DECL
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
#define FM(r) { __m512 av = _mm512_set1_ps(a[r]); \
        c##r##a = _mm512_fmadd_ps(av, b0, c##r##a); \
        c##r##b = _mm512_fmadd_ps(av, b1, c##r##b); }
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5)
        FM(6) FM(7) FM(8) FM(9) FM(10) FM(11)
#undef FM
        a += MR; b += NR;
    }
    if (mr == MR && nr == NR) {
#define ST(r) { float *cp = c + (size_t)(r) * ldc; \
        if (acc) { \
            _mm512_storeu_ps(cp, _mm512_add_ps(_mm512_loadu_ps(cp), c##r##a)); \
            _mm512_storeu_ps(cp + 16, _mm512_add_ps(_mm512_loadu_ps(cp + 16), c##r##b)); \
        } else { _mm512_storeu_ps(cp, c##r##a); _mm512_storeu_ps(cp + 16, c##r##b); } }
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
        ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
#undef ST
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
#define TS(r) _mm512_store_ps(tmp + (r) * NR, c##r##a); _mm512_store_ps(tmp + (r) * NR + 16, c##r##b);
        TS(0) TS(1) TS(2) TS(3) TS(4) TS(5)
        TS(6) TS(7) TS(8) TS(9) TS(10) TS(11)
#undef TS
        edge_store(tmp, c, ldc, mr, nr, acc);
    }
}

#elif defined(__AVX2__) && defined(__FMA__)

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
#define DECL(r) __m256 c##r##a = _mm256_setzero_ps(), c##r##b = _mm256_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
#undef DECL
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
#define FM(r) { __m256 av = _mm256_broadcast_ss(a + (r)); \
        c##r##a = _mm256_fmadd_ps(av, b0, c##r##a); \
        c##r##b = _mm256_fmadd_ps(av, b1, c##r##b); }
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5)
#undef FM
        a += MR; b += NR;
    }
    if (mr == MR && nr == NR) {
#define ST(r) { float *cp = c + (size_t)(r) * ldc; \
        if (acc) { \
            _mm256_storeu_ps(cp, _mm256_add_ps(_mm256_loadu_ps(cp), c##r##a)); \
            _mm256_storeu_ps(cp + 8, _mm256_add_ps(_mm256_loadu_ps(cp + 8), c##r##b)); \
        } else { _mm256_storeu_ps(cp, c##r##a); _mm256_storeu_ps(cp + 8, c##r##b); } }
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
#undef ST
    } else {
        float tmp[MR * NR] __attribute__((aligned(32)));
#define TS(r) _mm256_store_ps(tmp + (r) * NR, c##r##a); _mm256_store_ps(tmp + (r) * NR + 8, c##r##b);
        TS(0) TS(1) TS(2) TS(3) TS(4) TS(5)
#undef TS
        edge_store(tmp, c, ldc, mr, nr, acc);
    }
}

#else

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    float tmp[MR * NR];
    memset(tmp, 0, sizeof(tmp));
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            for (int j = 0; j < NR; j++)
                tmp[r * NR + j] += av * b[j];
        }
        a += MR; b += NR;
    }
    edge_store(tmp, c, ldc, mr, nr, acc);
}

#endif

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    const int mp = (n + MR - 1) / MR;
    const int np = (n + NR - 1) / NR;
    const int ncwp = NCW / NR;
    const int ntn = (np + ncwp - 1) / ncwp;

    float *Ap = ensure(&bufA, &capA, (size_t)mp * MR * n);
    float *Bp = ensure(&bufB, &capB, (size_t)np * NR * n);

    int nth = omp_get_max_threads();
    int mpt = (int)(((long)mp * ntn) / (4L * nth));
    if (mpt < 1) mpt = 1;
    if (mpt > 8) mpt = 8;
    const int ntm = (mp + mpt - 1) / mpt;
    const int ntasks = ntm * ntn;

    #pragma omp parallel
    {
        /* Pack A: panel p holds rows p*MR..p*MR+MR-1, layout [k][MR]. */
        #pragma omp for schedule(static) nowait
        for (int p = 0; p < mp; p++) {
            float *dst = Ap + (size_t)p * n * MR;
            int i0 = p * MR;
            int mr = n - i0 < MR ? n - i0 : MR;
            for (int k0 = 0; k0 < n; k0 += 64) {
                int k1 = k0 + 64 < n ? k0 + 64 : n;
                for (int r = 0; r < MR; r++) {
                    if (r < mr) {
                        const float *src = A + (size_t)(i0 + r) * n;
                        for (int k = k0; k < k1; k++) dst[(size_t)k * MR + r] = src[k];
                    } else {
                        for (int k = k0; k < k1; k++) dst[(size_t)k * MR + r] = 0.0f;
                    }
                }
            }
        }

        /* Pack B: panel q holds cols q*NR..q*NR+NR-1, layout [k][NR]. */
        #pragma omp for schedule(static)
        for (int k = 0; k < n; k++) {
            const float *src = B + (size_t)k * n;
            for (int q = 0; q < np; q++) {
                float *dst = Bp + (size_t)q * n * NR + (size_t)k * NR;
                int j0 = q * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                if (nr == NR) {
                    memcpy(dst, src + j0, NR * sizeof(float));
                } else {
                    memcpy(dst, src + j0, nr * sizeof(float));
                    memset(dst + nr, 0, (NR - nr) * sizeof(float));
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int tm = t / ntn, tn = t % ntn;
            int p0 = tm * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
            int q0 = tn * ncwp, q1 = q0 + ncwp < np ? q0 + ncwp : np;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                for (int p = p0; p < p1; p++) {
                    const float *a = Ap + (size_t)p * n * MR + (size_t)pc * MR;
                    int i0 = p * MR;
                    int mr = n - i0 < MR ? n - i0 : MR;
                    for (int q = q0; q < q1; q++) {
                        const float *b = Bp + (size_t)q * n * NR + (size_t)pc * NR;
                        int j0 = q * NR;
                        int nr = n - j0 < NR ? n - j0 : NR;
                        kernel(kc, a, b, C + (size_t)i0 * n + j0, n, mr, nr, pc > 0);
                    }
                }
            }
        }
    }
}
